'use strict';

var escape = require('../helpers/escape');

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	//Create the question
	var question = options.question ? options.question : 'date',
		name = options.name ? options.name : question,
		attrib = escape.htmlAttributeEscape(JSON.stringify(options), { singleQuotes: true });

	//HTML
	var $html = $(
		'<div class="form-group">' +
			'<h3>' + question + '</h3>' +
			'<div class="input-group date">' +
				'<input type="text" class="form-control f3-date" name="' + name + '" data-options=\'' + attrib + '\' readonly>' +
				'<span class="input-group-addon"><span class="glyphicon glyphicon-calendar"></span></span>' +
			'</div>' +
		'</div>'
	);

	//Default datetimepicker config
	var defaultConfig = {
		pickTime: false,
		showToday: false
	};

	//Explicit config
	var config = options.config === undefined ? {} : options.config;

	//Set the timepicker
	$html.find('.date, input').datetimepicker($.extend(defaultConfig, config));

	//Bind change
	$html.find('input').on('change', function() {

		//Publish the event
		PubSub.publish('f3.date', {
			'trigger': this,
			'event': 'change'
		});

	}).on('click', function() {

		//Publish the event
		PubSub.publish('f3.date', {
			'trigger': this,
			'event': 'click'
		});

	});

	return $html;

}

function _read(options, value) {

	return {
		question: options.question || 'date',
		name: options.name || options.question,

		text: value,
		value: value
	};

}

module.exports = {
	render: _render,
	read: _read,
	name: 'date'
};
